shader_type canvas_item;
// Test-only approximation of nofacer CRT plugin (curvature, mask, vignette, chroma).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float curvature : hint_range(0.0, 0.25) = 0.08;
uniform float scanline_strength : hint_range(0.0, 0.5) = 0.12;
uniform float mask_strength : hint_range(0.0, 1.0) = 0.35;
uniform float vignette : hint_range(0.0, 1.0) = 0.22;
uniform float chroma : hint_range(0.0, 0.01) = 0.0025;

vec2 curve_uv(vec2 uv, float amount) {
	vec2 c = uv - 0.5;
	float r2 = dot(c, c);
	return uv + c * r2 * amount;
}

void fragment() {
	vec2 uv = curve_uv(SCREEN_UV, curvature);
	if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
		COLOR = vec4(0.0, 0.0, 0.0, 1.0);
		return;
	}
	float off = chroma;
	vec3 col;
	col.r = texture(screen_texture, uv + vec2(off, 0.0)).r;
	col.g = texture(screen_texture, uv).g;
	col.b = texture(screen_texture, uv - vec2(off, 0.0)).b;
	float scan = sin(uv.y * 800.0) * 0.5 + 0.5;
	col *= 1.0 - scan * scanline_strength;
	float mask = sin(uv.x * 900.0) * 0.5 + 0.5;
	col = mix(col, col * 0.85, mask * mask_strength);
	vec2 d = uv - 0.5;
	float vig = 1.0 - dot(d, d) * vignette * 4.0;
	col *= vig;
	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
// Test-only VHS / tape degradation approximation (GodotRetro-inspired).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float noise_strength : hint_range(0.0, 0.3) = 0.08;
uniform float bleed : hint_range(0.0, 0.05) = 0.012;
uniform float jitter : hint_range(0.0, 0.02) = 0.004;

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void fragment() {
	vec2 uv = SCREEN_UV;
	float t = floor(TIME * 12.0);
	float j = (hash(vec2(t, uv.y)) - 0.5) * jitter;
	uv.x += j;
	vec3 col;
	col.r = texture(screen_texture, uv + vec2(bleed, 0.0)).r;
	col.g = texture(screen_texture, uv).g;
	col.b = texture(screen_texture, uv - vec2(bleed, 0.0)).b;
	float n = hash(uv * 1200.0 + t) - 0.5;
	col += n * noise_strength;
	float band = step(0.97, hash(vec2(uv.y * 40.0, t)));
	col = mix(col, col * 0.6, band * 0.35);
	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
// C1: posterization + ordered dither + light outline.

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform vec4 c_black : source_color = vec4(0.0, 0.0, 0.0, 1.0);
uniform vec4 c_dark : source_color = vec4(0.29, 0.0, 0.0, 1.0);
uniform vec4 c_red : source_color = vec4(0.9, 0.0, 0.0, 1.0);
uniform vec4 c_light : source_color = vec4(0.85, 0.85, 0.85, 1.0);
uniform float levels : hint_range(2.0, 8.0) = 4.0;

float bayer4(vec2 p) {
	vec2 m = mod(floor(p), 4.0);
	float idx = m.x + m.y * 4.0;
	float b[16] = float[16](
		0.0, 8.0, 2.0, 10.0,
		12.0, 4.0, 14.0, 6.0,
		3.0, 11.0, 1.0, 9.0,
		15.0, 7.0, 13.0, 5.0
	);
	return b[int(idx)] / 16.0;
}

vec4 map_palette(float lum) {
	if (lum < 0.2) return c_black;
	if (lum < 0.45) return c_dark;
	if (lum < 0.72) return c_red;
	return c_light;
}

void fragment() {
	vec2 uv = SCREEN_UV;
	vec2 px = 1.0 / vec2(textureSize(screen_texture, 0));
	vec3 src = texture(screen_texture, uv).rgb;
	float lum = dot(src, vec3(0.299, 0.587, 0.114));
	float edge = length(texture(screen_texture, uv + vec2(px.x, 0.0)).rgb - texture(screen_texture, uv - vec2(px.x, 0.0)).rgb);
	edge += length(texture(screen_texture, uv + vec2(0.0, px.y)).rgb - texture(screen_texture, uv - vec2(0.0, px.y)).rgb);
	lum = floor(lum * levels) / levels;
	float d = bayer4(gl_FragCoord.xy);
	lum += (d - 0.5) * (1.0 / levels);
	vec4 mapped = map_palette(clamp(lum, 0.0, 1.0));
	if (edge > 0.35) {
		mapped = c_black;
	}
	COLOR = vec4(mapped.rgb, 1.0);
}

shader_type canvas_item;
// C2: 4-band AXEL palette + 4x4 Bayer dither.

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform vec4 c_black : source_color = vec4(0.0, 0.0, 0.0, 1.0);
uniform vec4 c_dark : source_color = vec4(0.26, 0.0, 0.0, 1.0);
uniform vec4 c_red : source_color = vec4(0.88, 0.0, 0.0, 1.0);
uniform vec4 c_light : source_color = vec4(0.0, 0.0, 0.0, 1.0);

float bayer4(vec2 p) {
	vec2 m = mod(floor(p), 4.0);
	int idx = int(m.x + m.y * 4.0);
	const float b[16] = float[16](
		0.0/16.0, 8.0/16.0, 2.0/16.0, 10.0/16.0,
		12.0/16.0, 4.0/16.0, 14.0/16.0, 6.0/16.0,
		3.0/16.0, 11.0/16.0, 1.0/16.0, 9.0/16.0,
		15.0/16.0, 7.0/16.0, 13.0/16.0, 5.0/16.0
	);
	return b[idx];
}

void fragment() {
	float lum = dot(texture(screen_texture, SCREEN_UV).rgb, vec3(0.299, 0.587, 0.114));
	float d = bayer4(gl_FragCoord.xy);
	float t0 = 0.10;
	float t1 = 0.28;
	float t2 = 0.58;
	float adj = lum + (d - 0.5) * 0.08;
	vec4 out_col = c_black;
	if (adj < t0) out_col = c_black;
	else if (adj < t1) out_col = c_dark;
	else if (adj < t2) out_col = c_red;
	else out_col = c_light;
	COLOR = vec4(out_col.rgb, 1.0);
}

shader_type canvas_item;
// C3: perceptual palette snap (Oklab-inspired approximation).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform vec4 c_black : source_color = vec4(0.0, 0.0, 0.0, 1.0);
uniform vec4 c_dark : source_color = vec4(0.26, 0.0, 0.0, 1.0);
uniform vec4 c_red : source_color = vec4(0.88, 0.0, 0.0, 1.0);
uniform vec4 c_light : source_color = vec4(0.0, 0.0, 0.0, 1.0);

vec3 to_oklab(vec3 c) {
	vec3 lms = mat3(
		vec3(0.4122214708, 0.5363325363, 0.0514459929),
		vec3(0.2119034982, 0.6806995451, 0.1073969566),
		vec3(0.0883024619, 0.2817188376, 0.6299787005)
	) * c;
	lms = pow(max(lms, vec3(0.0)), vec3(1.0 / 3.0));
	return vec3(
		dot(lms, vec3(0.2104542553, 0.7936177850, -0.0040720468)),
		dot(lms, vec3(1.9779984951, -2.4285922050, 0.4505937099)),
		dot(lms, vec3(0.0259040371, 0.7827717662, -0.8086757660))
	);
}

float dist_oklab(vec3 a, vec3 b) {
	vec3 d = a - b;
	return dot(d, d);
}

void fragment() {
	vec3 rgb = texture(screen_texture, SCREEN_UV).rgb;
	vec3 lab = to_oklab(rgb);
	vec4 palette[4] = vec4[4](c_black, c_dark, c_red, c_light);
	vec3 plabs[4];
	for (int i = 0; i < 4; i++) {
		plabs[i] = to_oklab(palette[i].rgb);
	}
	float best = 1e9;
	vec3 pick = rgb;
	for (int i = 0; i < 4; i++) {
		float d = dist_oklab(lab, plabs[i]);
		if (d < best) {
			best = d;
			pick = palette[i].rgb;
		}
	}
	COLOR = vec4(pick, 1.0);
}

shader_type canvas_item;
// C4: pixelation + noise dither + palette map (VesperaFX-style test approximation).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float pixel_size : hint_range(1.0, 8.0) = 3.0;
uniform float dither_strength : hint_range(0.0, 0.2) = 0.06;

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

vec4 map_axel(float lum) {
	if (lum < 0.12) return vec4(0.0, 0.0, 0.0, 1.0);
	if (lum < 0.35) return vec4(0.26, 0.0, 0.0, 1.0);
	if (lum < 0.62) return vec4(0.88, 0.0, 0.0, 1.0);
	return vec4(0.0, 0.0, 0.0, 1.0);
}

void fragment() {
	ivec2 size = textureSize(screen_texture, 0);
	vec2 px = vec2(pixel_size) / vec2(size);
	vec2 uv = floor(SCREEN_UV / px) * px + px * 0.5;
	float lum = dot(texture(screen_texture, uv).rgb, vec3(0.299, 0.587, 0.114));
	lum += (hash(gl_FragCoord.xy) - 0.5) * dither_strength;
	COLOR = map_axel(clamp(lum, 0.0, 1.0));
}

shader_type canvas_item;
// D: CRT display — RGB shadow mask + scanlines + mild bloom.

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float mask_pitch : hint_range(200.0, 1200.0) = 720.0;
uniform float scan_strength : hint_range(0.0, 0.4) = 0.14;
uniform float glow : hint_range(0.0, 0.5) = 0.12;

void fragment() {
	vec2 uv = SCREEN_UV;
	vec2 px = 1.0 / vec2(textureSize(screen_texture, 0));
	vec3 col = texture(screen_texture, uv).rgb;
	vec3 blur = (
		texture(screen_texture, uv + vec2(px.x, 0.0)).rgb +
		texture(screen_texture, uv - vec2(px.x, 0.0)).rgb +
		texture(screen_texture, uv + vec2(0.0, px.y)).rgb +
		texture(screen_texture, uv - vec2(0.0, px.y)).rgb
	) * 0.25;
	col = mix(col, blur, glow);
	float tri = abs(fract(uv.x * mask_pitch) - 0.5);
	vec3 mask = vec3(
		clamp(1.0 - tri * 3.0, 0.0, 1.0),
		clamp(1.0 - abs(tri * 3.0 - 1.0), 0.0, 1.0),
		clamp(1.0 - abs(tri * 3.0 - 2.0), 0.0, 1.0)
	);
	col *= mix(vec3(1.0), mask, 0.55);
	float scan = sin(uv.y * 700.0) * 0.5 + 0.5;
	col *= 1.0 - scan * scan_strength;
	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
// E: CRT with luminance-preserving scanlines + subtle curvature.

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float curvature : hint_range(0.0, 0.2) = 0.06;
uniform float scan_strength : hint_range(0.0, 0.35) = 0.1;
uniform float phosphor : hint_range(0.0, 1.0) = 0.25;

vec2 curve_uv(vec2 uv) {
	vec2 c = uv - 0.5;
	return uv + c * dot(c, c) * curvature;
}

void fragment() {
	vec2 uv = curve_uv(SCREEN_UV);
	vec3 col = texture(screen_texture, uv).rgb;
	float lum = dot(col, vec3(0.299, 0.587, 0.114));
	float scan = sin(uv.y * 650.0) * 0.5 + 0.5;
	float factor = 1.0 - scan * scan_strength;
	vec3 scaled = col * factor;
	float lum2 = dot(scaled, vec3(0.299, 0.587, 0.114));
	if (lum2 > 0.001) {
		col = scaled * (lum / lum2);
	} else {
		col = scaled;
	}
	vec3 ph = vec3(
		sin(uv.x * 900.0) * 0.5 + 0.5,
		sin(uv.x * 900.0 + 2.094) * 0.5 + 0.5,
		sin(uv.x * 900.0 + 4.188) * 0.5 + 0.5
	);
	col = mix(col, col * ph, phosphor * 0.35);
	COLOR = vec4(col, 1.0);
}

extends SceneTree
## Scene 1.1 visual style sweep: baseline + options A/B/C1-C4/D/E.
##
## Run from repo root:
##   tools\cmd\godot.cmd --path AXEL/axel_project -s res://test/visual_style/capture_scene_1_1_style_sweep.gd
##
## Optional env:
##   AXEL_STYLE_VARIANT=baseline   (single variant; default = all)
##   AXEL_STYLE_OUTPUT=user://style_sweep_1_1  (override output dir)
##
## Exit 0 when all requested PNGs are written; 1 on failure.

const VariantMatrix := preload("res://test/visual_style/variant_matrix.gd")
const StyleOverlayApplier := preload("res://test/visual_style/style_overlay_applier.gd")
const InputEventDriverScript := preload("res://test/bots/input_event_driver.gd")
const BotScenarioRunnerScript := preload("res://test/bots/scenario_runner.gd")

const _SCENE := VariantMatrix.SCENE_PATH
const _INTRO_WAIT_SEC := 0.15
const _WALK_FRAMES := 120
const _SETTLE_FRAMES := 6
const _RENDER_WARMUP_FRAMES := 4

var _output_dir := ""


func _init() -> void:
	OS.set_environment("AXEL_SKIP_INTRO", "1")
	_output_dir = _resolve_output_dir()
	_ensure_output_dir()
	call_deferred("_main")


func _resolve_output_dir() -> String:
	if OS.has_environment("AXEL_STYLE_OUTPUT") and not OS.get_environment("AXEL_STYLE_OUTPUT").is_empty():
		return OS.get_environment("AXEL_STYLE_OUTPUT")
	return VariantMatrix.OUTPUT_DIR


func _ensure_output_dir() -> void:
	var abs := ProjectSettings.globalize_path(_output_dir)
	DirAccess.make_dir_recursive_absolute(abs)


func _main() -> void:
	var only_id := ""
	if OS.has_environment("AXEL_STYLE_VARIANT"):
		only_id = OS.get_environment("AXEL_STYLE_VARIANT").strip_edges()

	var specs: Array[Dictionary] = []
	for v in VariantMatrix.VARIANTS:
		if only_id.is_empty() or String(v["id"]) == only_id:
			specs.append(v)

	if specs.is_empty():
		push_error("No variants matched filter '%s'." % only_id)
		quit(1)
		return

	var failures: Array[String] = []
	for spec in specs:
		var ok := await _capture_one(spec)
		if not ok:
			failures.append(String(spec["id"]))

	if failures.is_empty():
		print("Style sweep OK: %d captures -> %s" % [specs.size(), ProjectSettings.globalize_path(_output_dir)])
		_print_manifest()
		quit(0)
	else:
		push_error("Style sweep FAILED variants: %s" % ", ".join(failures))
		quit(1)


func _capture_one(spec: Dictionary) -> bool:
	var variant_id := String(spec["id"])
	print("--- Capturing variant: %s (%s) ---" % [variant_id, spec["label"]])

	var err := change_scene_to_file(_SCENE)
	if err != OK:
		push_error("change_scene_to_file failed (%d) for %s" % [err, _SCENE])
		return false

	for _i in 4:
		await process_frame

	if current_scene == null:
		push_error("current_scene null after load.")
		return false

	_hide_dialogue_for_capture()
	var applier := StyleOverlayApplier.new(current_scene)
	applier.apply_variant(spec)

	await create_timer(_INTRO_WAIT_SEC).timeout

	var driver := InputEventDriverScript.new(self, false)
	var runner := BotScenarioRunnerScript.new(self, driver, false)
	var commands: Array = [
		{"op": "hold", "key": KEY_D, "frames": _WALK_FRAMES},
		{"op": "wait_frames", "frames": _SETTLE_FRAMES},
	]
	var movement_ok := await runner.run(commands)
	driver.release_all()
	if not movement_ok:
		push_error("Movement failed for %s: %s" % [variant_id, runner.failure_summary()])
		return false

	for _i in _RENDER_WARMUP_FRAMES:
		await process_frame

	var png_name := String(spec["png"])
	var out_path := "%s/%s" % [_output_dir, png_name]
	if not _save_viewport_png(out_path):
		push_error("PNG save failed: %s" % out_path)
		return false

	print("Wrote %s" % ProjectSettings.globalize_path(out_path))
	current_scene.queue_free()
	for _i in 2:
		await process_frame
	return true


func _hide_dialogue_for_capture() -> void:
	var dlg := current_scene.get_node_or_null("TopDialogueOverlay")
	if dlg == null:
		return
	if dlg.has_method("hide_line"):
		dlg.hide_line()
	dlg.visible = false


func _save_viewport_png(user_path: String) -> bool:
	var vp := root.get_viewport()
	if vp == null:
		return false
	var tex := vp.get_texture()
	if tex == null:
		return false
	var img := tex.get_image()
	if img == null or img.is_empty():
		return false
	var err := img.save_png(user_path)
	return err == OK


func _print_manifest() -> void:
	var payload := {
		"scene": _SCENE,
		"output_dir": ProjectSettings.globalize_path(_output_dir),
		"viewport": Vector2i(
			ProjectSettings.get_setting("display/window/size/viewport_width"),
			ProjectSettings.get_setting("display/window/size/viewport_height")
		),
		"walk_frames": _WALK_FRAMES,
		"variants": VariantMatrix.variant_ids(),
	}
	print("STYLE_SWEEP_MANIFEST %s" % JSON.stringify(payload))

input.new_string:
	set_process_unhandled_input(true)
	if _should_skip_intro():
		return
	_run_intro_dialogue()


func _should_skip_intro() -> bool:
	return OS.has_environment("AXEL_SKIP_INTRO") and OS.get_environment("AXEL_SKIP_INTRO") == "1"

