shader_type canvas_item;
// Style-sweep Option A: CRT + outline-aware boost (detects line art edges, applies full CRT like player).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float curvature : hint_range(0.0, 0.25) = 0.08;
uniform float scanline_strength : hint_range(0.0, 0.5) = 0.12;
uniform float mask_strength : hint_range(0.0, 1.0) = 0.35;
uniform float vignette : hint_range(0.0, 1.0) = 0.22;
uniform float chroma : hint_range(0.0, 0.01) = 0.0025;

uniform float outline_threshold : hint_range(0.0, 1.0) = 0.12;
uniform float outline_softness : hint_range(0.01, 0.5) = 0.08;
uniform float outline_boost : hint_range(0.0, 2.0) = 1.0;
uniform float outline_chroma_mult : hint_range(1.0, 6.0) = 3.2;
uniform float outline_scan_mult : hint_range(1.0, 4.0) = 2.2;
uniform float outline_mask_mult : hint_range(1.0, 4.0) = 1.8;
uniform float outline_red_bias : hint_range(0.0, 1.0) = 0.35;

vec2 curve_uv(vec2 uv, float amount) {
	vec2 c = uv - 0.5;
	float r2 = dot(c, c);
	return uv + c * r2 * amount;
}

float sample_lum(vec2 uv) {
	vec3 c = texture(screen_texture, uv).rgb;
	return dot(c, vec3(0.299, 0.587, 0.114));
}

float outline_mask_at(vec2 uv) {
	vec2 px = 1.0 / vec2(textureSize(screen_texture, 0));
	float lum_c = sample_lum(uv);
	float lum_l = sample_lum(uv - vec2(px.x, 0.0));
	float lum_r = sample_lum(uv + vec2(px.x, 0.0));
	float lum_u = sample_lum(uv - vec2(0.0, px.y));
	float lum_d = sample_lum(uv + vec2(0.0, px.y));
	float lum_ul = sample_lum(uv - px);
	float lum_ur = sample_lum(uv + vec2(px.x, -px.y));
	float lum_dl = sample_lum(uv + vec2(-px.x, px.y));
	float lum_dr = sample_lum(uv + px);

	float edge = 0.0;
	edge = max(edge, abs(lum_c - lum_l));
	edge = max(edge, abs(lum_c - lum_r));
	edge = max(edge, abs(lum_c - lum_u));
	edge = max(edge, abs(lum_c - lum_d));
	edge = max(edge, abs(lum_c - lum_ul));
	edge = max(edge, abs(lum_c - lum_ur));
	edge = max(edge, abs(lum_c - lum_dl));
	edge = max(edge, abs(lum_c - lum_dr));

	vec3 src = texture(screen_texture, uv).rgb;
	float red_line = smoothstep(0.25, 0.55, src.r - max(src.g, src.b));
	float bright_line = smoothstep(0.45, 0.85, lum_c);

	float edge_mask = smoothstep(
		outline_threshold - outline_softness,
		outline_threshold + outline_softness,
		edge
	);
	return clamp(max(edge_mask, max(red_line, bright_line) * outline_red_bias), 0.0, 1.0);
}

vec3 apply_crt(vec2 uv, float scan_mul, float mask_mul, float chroma_mul) {
	float off = chroma * chroma_mul;
	vec3 col;
	col.r = texture(screen_texture, uv + vec2(off, 0.0)).r;
	col.g = texture(screen_texture, uv).g;
	col.b = texture(screen_texture, uv - vec2(off, 0.0)).b;
	float scan = sin(uv.y * 800.0) * 0.5 + 0.5;
	col *= 1.0 - scan * scanline_strength * scan_mul;
	float mask = sin(uv.x * 900.0) * 0.5 + 0.5;
	col = mix(col, col * 0.85, mask * mask_strength * mask_mul);
	vec2 d = uv - 0.5;
	float vig = 1.0 - dot(d, d) * vignette * 4.0;
	col *= vig;
	return col;
}

void fragment() {
	vec2 uv = curve_uv(SCREEN_UV, curvature);
	vec3 col = vec3(0.0);
	if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
		float omask = outline_mask_at(uv);
		vec3 base_col = apply_crt(uv, 1.0, 1.0, 1.0);
		vec3 outline_col = apply_crt(
			uv,
			outline_scan_mult,
			outline_mask_mult,
			outline_chroma_mult
		);
		col = mix(base_col, outline_col, omask * outline_boost);
	}
	COLOR = vec4(col, 1.0);
}

